import json
with open('/root/DATA/products/CoachForce.json') as f:
    data = json.load(f)

# Get messages between 2026-04-11 and 2026-04-12 in planning-CoFoAIX
slack = data['slack']
for i, msg in enumerate(slack):
    if msg['Channel']['name'] == 'planning-CoFoAIX':
        ts = msg['Message']['User'].get('timestamp', '')
        if ts >= '2026-04-11' and ts < '2026-04-13':
            user = msg['Message']['User']['userId']
            text = msg['Message']['User']['text']
            print(f'[{ts}] {user}: {text}')
            replies = msg.get('ThreadReplies', [])
            if replies:
                for r in replies:
                    if isinstance(r, dict) and 'User' in r:
                        print(f'  Reply [{r["User"].get("timestamp","")}] {r["User"]["userId"]}: {r["User"]["text"]}')
            print()
